alter table public.plate_art_templates add column qr_count smallint not null default 1 check (qr_count in (1, 2));
alter table public.nfc_plates add column qr_count smallint;
update public.plate_art_templates set qr_count = 2 where id in ('6d613645-4ba2-4f4b-a9c1-0a0fd8a03d31', '7eb75a5f-d72a-4a3e-8654-852393d93d0b');
update public.nfc_plates p set qr_count = t.qr_count from public.plate_batches b join public.plate_art_templates t on t.id = b.template_id where p.batch_id = b.id and p.qr_count is null;
alter table public.nfc_plates alter column qr_count set not null, alter column qr_count set default 1, add constraint nfc_plates_qr_count_check check (qr_count in (1, 2));
create or replace function public.create_nfc_plate_batch(requested_template_id uuid, requested_quantity integer) returns jsonb language plpgsql security definer set search_path = public as $$ declare b public.plate_batches; p public.nfc_plates; c text; count_qr smallint; begin if not public.is_platform_admin() then return null; end if; if requested_quantity not between 1 and 200 then raise exception 'Quantity must be between 1 and 200'; end if; select qr_count into count_qr from public.plate_art_templates where id=requested_template_id; if not found then raise exception 'Template not found'; end if; insert into public.plate_batches(batch_number,template_id,quantity,created_by) values('LT-'||to_char(now(),'YYYYMMDD')||'-'||lpad(nextval('public.plate_batch_number_seq')::text,6,'0'),requested_template_id,requested_quantity,auth.uid()) returning * into b; for i in 1..requested_quantity loop c:='PL-'||lpad(nextval('public.nfc_plate_number_seq')::text,6,'0'); insert into public.nfc_plates(public_code,wifi_public_code,display_code,batch_id,qr_count) values(encode(extensions.gen_random_bytes(12),'hex'),encode(extensions.gen_random_bytes(12),'hex'),c,b.id,count_qr) returning * into p; insert into public.nfc_plate_history(plate_id,action,next_status,changed_by,metadata) values(p.id,'created','available',auth.uid(),jsonb_build_object('batch_id',b.id)); end loop; return jsonb_build_object('id',b.id,'batch_number',b.batch_number,'quantity',b.quantity); end; $$;
